// PostToolUse(Write|Edit) hook: after an edit to either types.ts, point at
// the generated-mirror workflow — server/src/types.ts is the source of
// truth; web/src/types.ts is generated by scripts/sync-types.mjs.
const raw = await new Promise((resolve) => {
  let s = "";
  process.stdin.on("data", (d) => (s += d)).on("end", () => resolve(s || "{}"));
});

let file = "";
try {
  file = (JSON.parse(raw).tool_input?.file_path ?? "").replaceAll("\\", "/");
} catch {
  process.exit(0);
}

const m = file.match(/\/(server|web)\/src\/types\.ts$/);
if (!m) process.exit(0);

const editedServer = m[1] === "server";

const systemMessage = editedServer
  ? "server/src/types.ts is the contract's source of truth — regenerate the web mirror: node scripts/sync-types.mjs"
  : "web/src/types.ts is GENERATED — do not hand-edit; change server/src/types.ts and run node scripts/sync-types.mjs";

const additionalContext = editedServer
  ? "You just edited server/src/types.ts, the API contract's single source of truth. web/src/types.ts is GENERATED from it — run `node scripts/sync-types.mjs` from the repo root (or /sync-types) before finishing; CI's `contract` job fails when the mirror is stale."
  : "web/src/types.ts is GENERATED from server/src/types.ts. If this change belongs in the contract, make it in server/src/types.ts and regenerate with `node scripts/sync-types.mjs` (or /sync-types); hand-edits will fail CI's `contract` job.";

console.log(
  JSON.stringify({
    systemMessage,
    hookSpecificOutput: {
      hookEventName: "PostToolUse",
      additionalContext,
    },
  })
);
